import Header from '../src/Components/Header'
import Carousel from './Components/Carousel';
import Categories from './Components/Categories';
import Footer from './Components/Footer';

function HomePage() {
  return (
    <div>
      <Header/>
      <Carousel/>
      <Categories/>
      <Footer/>
    </div>
  );
}

export default HomePage;
